def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opps = []
    prev_bids = []
    urgent_prev_bids = []
    rich_threat_bids = []

    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opps.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                    urgent_prev_bids.append(float(bid))
                if opp.get('budget', 0) >= budget * 0.8:
                    rich_threat_bids.append(float(bid))

    if not alive_opps:
        return float(min(budget, 20.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    urgent_high = max(urgent_prev_bids) if urgent_prev_bids else highest_prev
    rich_high = max(rich_threat_bids) if rich_threat_bids else highest_prev

    scarcity = (supply <= 16)
    comfortable = (supply >= 22)
    critical_self = (hp <= 3 or no_water >= 1)
    very_safe = (hp >= 8 and no_water == 0)

    target = 0.0

    if critical_self:
        if scarcity:
            target = max(68.0, highest_prev + 2.0, urgent_high + 1.0)
        else:
            target = max(58.0, highest_prev + 1.5)
    elif scarcity:
        if very_safe and highest_prev >= 75.0:
            target = 18.0
        else:
            target = max(52.0, rich_high + 1.5)
    elif comfortable:
        if highest_prev >= 85.0 and very_safe:
            target = 16.0
        else:
            target = max(28.0, min(48.0, highest_prev * 0.72))
    else:
        if highest_prev >= 80.0 and very_safe:
            target = 20.0
        else:
            target = max(36.0, min(60.0, highest_prev + 1.0))

    if day >= 8:
        if hp <= 5:
            target = max(target, 62.0)
        elif budget < DAILY_SALARY * 2:
            target = min(target, 45.0)

    if budget < target:
        if critical_self:
            return float(max(0.0, budget))
        return float(max(0.0, min(budget, target)))

    return float(max(0.0, min(budget, target)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 1))

    hp = float(my_status.get('hp', 0.0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opponents = [o for o in opponents_status.values() if bool(o.get('alive', False))]

    # If we are in danger, bid to secure water.
    if hp <= 2 or no_water_days >= 2:
        target = DAILY_SALARY * 0.95
        return max(0.0, min(budget, target))

    # Use only yesterday's previous_trace to infer pressure.
    prev_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {}) or {}
        if prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev.get('bid')))
            except Exception:
                pass

    # Estimate how contested it was yesterday.
    if prev_bids:
        highest = max(prev_bids)
        second = sorted(prev_bids)[-2] if len(prev_bids) >= 2 else highest

        # If Cindy-like behavior (very high bids) likely continues, we bid just enough to stay in the game.
        if highest >= DAILY_SALARY * 0.85:
            # Keep bid moderate if we have decent hp; increase if our hp is dropping.
            pressure = 0.70 if hp >= 5 else 0.85
            # Also react to supply: if supply is near minimum, increase slightly.
            supply_factor = 0.08 if supply <= (MIN_SUPPLY + 1.0) else 0.0
            target = DAILY_SALARY * (pressure + supply_factor)
            # If yesterday's top bid was not far above our target, nudge upward.
            if highest - target > 15:
                target = min(DAILY_SALARY * 0.95, target + 10)
            return max(0.0, min(budget, target))

        # If bids were low, we can bid near a baseline to avoid wasting budget.
        baseline = DAILY_SALARY * 0.55
        # If we think others are conserving, bid slightly above second-highest.
        try:
            target = max(baseline, second + 2.0)
        except Exception:
            target = baseline
        # Supply scarcity: bid a bit more when supply is tight.
        if supply <= (MIN_SUPPLY + 2.0):
            target = max(target, DAILY_SALARY * 0.65)
        return max(0.0, min(budget, target))

    # No opponent bid info: choose a conservative mid bid.
    target = DAILY_SALARY * 0.58
    if supply <= (MIN_SUPPLY + 2.0):
        target = DAILY_SALARY * 0.68
    return max(0.0, min(budget, target))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    highest_prev_bid = 0.0
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
    else:
        highest_prev_bid = DAILY_SALARY * 0.55

    # 1. Critical HP / No Water Days: Bid very aggressively to survive
    if my_status['hp'] <= 2 or my_status['no_water_days'] >= 1:
        return min(my_status['budget'], DAILY_SALARY * 0.98)

    # 2. React to high opponent bids
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        if my_status['hp'] > 3:
            return min(my_status['budget'], max(DAILY_SALARY * 0.6, highest_prev_bid * 0.95))
        else:
            return min(my_status['budget'], highest_prev_bid + 5)

    # 3. General Competitive Bidding: Bid slightly above the highest previous bid
    if highest_prev_bid > 0:
        return min(my_status['budget'], max(DAILY_SALARY * 0.55, highest_prev_bid + 2))

    # 4. Default / Early Game Bidding, adjusted by supply scarcity
    current_supply = day_context['supply']
    if current_supply <= (MIN_SUPPLY + MAX_SUPPLY) / 2:
        return min(my_status['budget'], DAILY_SALARY * 0.7)
    else:
        return min(my_status['budget'], DAILY_SALARY * 0.6)

def get_bid(day_context, my_status, opponents_status):
